package com.worklyn.modules.payroll.model;
import org.springframework.data.annotation.Id;import org.springframework.data.mongodb.core.index.CompoundIndex;import org.springframework.data.mongodb.core.index.Indexed;import org.springframework.data.mongodb.core.mapping.Document;import java.math.BigDecimal;import java.time.Instant;
@Document(collection="payroll_records") @CompoundIndex(name="employee_period_unique",def="{'employeeId':1,'payrollPeriod':1}",unique=true)
public class PayrollRecord {@Id private String id;@Indexed private String employeeId;@Indexed private String payrollPeriod;private BigDecimal baseSalary;private Integer workingDays;private Integer presentDays;private Integer paidLeaveDays;private Integer unpaidLeaveDays;private BigDecimal grossPay;private BigDecimal taxDeduction;private BigDecimal netPay;private PayrollStatus status;private Instant processedAt;private String processedBy;private String idempotencyKey;
 public String getId(){return id;}public void setId(String v){id=v;}public String getEmployeeId(){return employeeId;}public void setEmployeeId(String v){employeeId=v;}public String getPayrollPeriod(){return payrollPeriod;}public void setPayrollPeriod(String v){payrollPeriod=v;}public BigDecimal getBaseSalary(){return baseSalary;}public void setBaseSalary(BigDecimal v){baseSalary=v;}public Integer getWorkingDays(){return workingDays;}public void setWorkingDays(Integer v){workingDays=v;}public Integer getPresentDays(){return presentDays;}public void setPresentDays(Integer v){presentDays=v;}public Integer getPaidLeaveDays(){return paidLeaveDays;}public void setPaidLeaveDays(Integer v){paidLeaveDays=v;}public Integer getUnpaidLeaveDays(){return unpaidLeaveDays;}public void setUnpaidLeaveDays(Integer v){unpaidLeaveDays=v;}public BigDecimal getGrossPay(){return grossPay;}public void setGrossPay(BigDecimal v){grossPay=v;}public BigDecimal getTaxDeduction(){return taxDeduction;}public void setTaxDeduction(BigDecimal v){taxDeduction=v;}public BigDecimal getNetPay(){return netPay;}public void setNetPay(BigDecimal v){netPay=v;}public PayrollStatus getStatus(){return status;}public void setStatus(PayrollStatus v){status=v;}public Instant getProcessedAt(){return processedAt;}public void setProcessedAt(Instant v){processedAt=v;}public String getProcessedBy(){return processedBy;}public void setProcessedBy(String v){processedBy=v;}public String getIdempotencyKey(){return idempotencyKey;}public void setIdempotencyKey(String v){idempotencyKey=v;}
}
